export function getServiceCityCopy(citySlug: string, serviceSlug: string): string[] | null {
  const b = SERVICE_CITY_COPY[citySlug]?.[serviceSlug];
  return b ? b.split(/\n\n+/).map((p) => p.trim()).filter(Boolean) : null;
}
